module retry_fsm(input logic clk,reset,start,ack,timeout,output logic req,done,error);
  typedef enum logic [2:0] {IDLE,ISSUE,WAIT,SUCCESS,FAIL} state_t;
  state_t state,next;
  logic [1:0] attempts;
  always_comb begin
    next=state;req=0;done=0;error=0;
    case(state)
      IDLE: if(start) next=ISSUE;
      ISSUE: begin req=1;next=WAIT;end
      WAIT: if(ack) next=SUCCESS; else if(timeout) next=(attempts==2)?FAIL:ISSUE;
      SUCCESS: begin done=1;next=IDLE;end
      FAIL: begin error=1;next=IDLE;end
    endcase
  end
  always_ff @(posedge clk) begin
    if(reset) begin state<=IDLE;attempts<=0;end
    else begin
      state<=next;
      if(state==IDLE) attempts<=0;
      else if(state==WAIT && timeout && attempts!=2) attempts<=attempts+1'b1;
    end
  end
endmodule

