module counted_fifo(input logic clk,reset,wr_en,rd_en,input logic [7:0] din,output logic [7:0] dout,output logic [3:0] count,output logic full,empty);
  logic [7:0] mem[0:7];
  logic [2:0] wptr,rptr;
  wire write_fire=wr_en && !full;
  wire read_fire=rd_en && !empty;
  always_ff @(posedge clk) begin
    if(reset) begin wptr<=0;rptr<=0;count<=0;dout<=0;end
    else begin
      if(write_fire) begin mem[wptr]<=din;wptr<=wptr+1'b1;end
      if(read_fire) begin dout<=mem[rptr];rptr<=rptr+1'b1;end
      case({write_fire,read_fire})
        2'b10:count<=count+1'b1;
        2'b01:count<=count-1'b1;
        default:count<=count;
      endcase
    end
  end
  assign full=(count==8);
  assign empty=(count==0);
endmodule

