module fwft2(input logic clk,reset,wr_en,rd_en,input logic [7:0] din,output logic [7:0] dout,output logic empty,full);
  logic [7:0] q0,q1;
  logic [1:0] count;
  always_ff @(posedge clk) begin
    if(reset) count<=0;
    else begin
      if(wr_en && !full && !(rd_en && !empty)) begin
        if(count==0)q0<=din; else q1<=din;
        count<=count+1'b1;
      end else if(rd_en && !empty && !(wr_en && !full)) begin
        q0<=q1;count<=count-1'b1;
      end else if(wr_en && !full && rd_en && !empty) begin
        if(count==1) q0<=din;
        else begin q0<=q1;q1<=din;end
      end
    end
  end
  assign dout=q0;
  assign empty=(count==0);
  assign full=(count==2);
endmodule

